command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FLEISCHPUPPE (ZERZAL)
//
// - Ziel: Sich selbst (Wirkender)
// - Dauer: Bis die Besetzung endet
// - direkte Effektanlage über Block 5
// - Wirkungsende über Block 6
// - persistente Wirkungsende-Daten
// - Wirkungskarte über Block 19.8
// - keine GM-Anfrage
// - keine Wesenprüfung
// - kein Registrierungsbutton
// - alte Effekte nur desselben Wirkenden ersetzen
// ==========================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;
    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Fleischpuppe", vollerName = "Fleischpuppe (Zerzal)", ahne = "Zerzal";
    const endeKey = "zerzalFleischpuppe";
    const endeText = "Die Besetzung endet, und das Zerzalkind erhält die Kontrolle über seinen Körper zurück – man nimmt die wahre Gestalt wieder an.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const findeFleischpuppeEffekte = (actor, casterUuid) => (actor?.effects || []).filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "isFleischpuppe") === true &&
        effect.getFlag("dsk", "casterUuid") === casterUuid
    );

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    };

    // +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Fleischpuppe Probe", "Fleischpuppe"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");

    const basisBeschreibung =
        `Das Zerzalkind leiht dem Geist seinen Körper. Der Geist kann ihn lenken. ` +
        `Das Zerzalkind kann zwar weiterhin sehen und hören, aber nicht eingreifen.` +
        `<br><br><b>Zielkategorie:</b> Sich selbst`;

    const dauerText = "Bis die Besetzung endet";

    // +++ 5 - ALTEN EIGENEN EFFEKT ERSETZEN +++++++++++++++++++

    const alteEffekte = findeFleischpuppeEffekte(casterActor, casterActor.uuid);

    if (alteEffekte.length) {
        await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
    }

    // +++ 6 - EFFEKT DIREKT ÜBER BLOCK 5 ++++++++++++++++++++++

    const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName, ahne,
        beschreibung: basisBeschreibung + `<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
        gabeZiel: "", qs, ziel: casterActor, showIcon: 1,
        flags: { dsk: {
            isFleischpuppe: true, casterUuid: casterActor.uuid, qs,
            wirkungsende: {
                sfName: endeKey, basisEffektName: vollerName,
                beschreibungFuerEnde: endeText
            }
        }}
    });

    if (!erzeugterEffekt) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Der Fleischpuppe-Effekt konnte nicht angelegt werden!");
    }

    // +++ 7 - EFFEKT KONTROLLIEREN ++++++++++++++++++++++++++++

    const endeDaten = erzeugterEffekt.getFlag("dsk", "wirkungsende");
    const effektErfolgreich =
        (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
        erzeugterEffekt.getFlag("dsk", "isFleischpuppe") === true &&
        erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName;

    if (!effektErfolgreich) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Fleischpuppe wurde nicht vollständig angelegt!");
    }

    // +++ 8 - WIRKUNGSKARTE ÜBER BLOCK 19.8 +++++++++++++++++++

    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung: basisBeschreibung, wirkender: casterName,
        ziele: [{ name: casterName, rolle: "Besetzter Körper" }],
        misserfolge: [], dauerText,
        gmBereich: false, angewendet: true, erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    // +++ 9 - QS AUFRÄUMEN ++++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

}).call(this);
